"""Bind the shared-rack integration to its native and source evidence.

Run immediately after native QA, before restoring routine screenshot outputs.
"""
import json,hashlib,shutil,subprocess
from pathlib import Path
root=Path(__file__).resolve().parents[1];source=root.parent/'Porsche_911'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
qa=read(root/'docs/porsche-native-qa.json');rack=read(root/'docs/porsche-native-rack-qa.json');suspension=read(root/'docs/porsche-native-suspension-qa.json');rear=read(root/'docs/porsche-shared-rack-rear-scope.json')
assert qa['passed'] and qa['checks']==143 and qa['failures']==0 and rack['passed'] and rack['poses']==195 and suspension['passed'] and rear['passed']
log=(root/'.tools/porsche-qa-session.log').read_text();latest=log[log.rfind(',session-start'):];checks=[v for v in latest.splitlines() if ',porsche-qa-check,' in v];assert len(checks)==143 and all('pass=1' in s for s in checks)
study=read(source/'reports/shared-rack-node-verification.json');assert study['passed'] and study['poses']==729
assert (source/'viewer/SuspensionKinematics.js').read_text().split('\n',1)[1]==(source/'scripts/study_shared_rack_suspension.js').read_text().split('\n',1)[1]
production=read(source/'reports/shared-rack-production-fixture.json');tested=read(source/'reports/shared-rack-baseline-fixture.json');assert all(production[k]==tested[k] for k in ['body','moving','poses'])
clearance=read(source/'reports/shared-rack-baseline-clearance.json')
for file in ['assets/porsche/gt3rs_hero.glb','assets/porsche/gt3rs_near.glb','assets/porsche/gt3rs_far.glb','src/breakwater/porsche_asset_data.hpp']:
 subprocess.run(['git','diff','--quiet','d251005','--',file],cwd=root,check=True)
before=root/'.tools/shared-rack-before-performance.json';after=root/'.tools/shared-rack-after-performance.json';a,b=read(before),read(after);assert b['passed'] and len(b['cases'])==8
performance=[]
for x,y in zip(a['cases'],b['cases']):
 assert x['name']==y['name'] and y['motion_and_render_state_passed']
 assert all(all(p[k]==q[k] for k in ['speed_mps','steering_control','position']) for p,q in zip(x['raw_frames'],y['raw_frames']))
 performance.append({'case':y['name'],'before_frame_median_ms':x['frame_wall_ms']['p50'],'after_frame_median_ms':y['frame_wall_ms']['p50'],'before_simulation_cpu_mean_ms':x['stages_ms']['simulation']['cpu_submit']['mean'],'after_simulation_cpu_mean_ms':y['stages_ms']['simulation']['cpu_submit']['mean']})
shutil.copy2(before,root/'docs/porsche-shared-rack-before-performance.json');shutil.copy2(after,root/'docs/porsche-native-performance.json')
for name,old in [('porsche-shared-rack-rest.png','porsche-native-suspension-rest.png'),('porsche-shared-rack-cross.png','porsche-native-suspension-cross.png'),('porsche-shared-rack-front.png','porsche-native-front.png')]:shutil.copy2(root/'screenshots'/old,root/'screenshots'/name)
report={'production_changed':True,'native_checks':143,'native_rack':rack,'native_suspension':suspension,'source_node_checks':study,'rear_scope':rear,'production_js_sha256':sha(source/'viewer/SuspensionKinematics.js'),'native_cpp_sha256':sha(root/'src/breakwater/porsche_suspension.cpp'),'native_controller_sha256':sha(root/'src/breakwater/porsche_native.cpp'),'validation_executable_sha256':sha(root/'build-native/ninja/bin/game.exe'),'geometry_assets_unchanged_from_commit':'d251005','rolling_projection':'CPU-only posed rig, cached by front/rear steering and four travel values; actual wheel directions are checked against Three-generated neutral/steered/asymmetric reference directions','rolling_checks':['wheel-spin-matches-straight-contact-distance','outside-wheels-roll-the-extra-track-distance','reverse-contact-distance-reverses-wheel-spin','steered-wheel-spin-projects-actual-posed-directions','wheel-spin-follows-asymmetric-suspension-heading'],'clearance':{'intersection_poses':clearance['poses_with_intersections'],'poses':clearance['pose_count'],'report_sha256':sha(source/'reports/shared-rack-baseline-clearance.json'),'production_fixture_sha256':sha(source/'reports/shared-rack-production-fixture.json'),'tested_fixture_sha256':sha(source/'reports/shared-rack-baseline-fixture.json'),'body_tires_and_all_pose_matrices_exactly_equal':True},'performance':performance,'driving_motion_traces_exactly_equal_to_previous_run':True,'captures':{n:sha(root/'screenshots'/n) for n in ['porsche-shared-rack-rest.png','porsche-shared-rack-cross.png','porsche-shared-rack-front.png']},'visual_review':'Inspected native cross-travel mechanism view: front arms, tie rods, spring/damper assemblies remain connected; fixed-length and shared-rack invariants have independent node checks.','limits':['Source-fitted game rack and link geometry; no OEM hardpoint or full variable-ratio calibration claim','Joint centers stay within the retained rack housing axial bounds; bore fit and all neighboring part collisions are not established','Front tire/painted-body contact remains in 87 of 165 source stress poses; this change is not a clearance fix','Additional CPU pose evaluation costs roughly 0.1 to 0.25 ms in the warm measured cases; frame timings vary and this is not a performance improvement claim','Native fixtures cover finite poses, not all continuous motions or all terrain states','Forza-level final fidelity, final clearance review and GitHub delivery remain incomplete'],'complete':False}
(root/'docs/porsche-shared-rack-review.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'native_checks':143,'native_reference_poses':195,'source_node_poses':729,'remaining_intersection_poses':clearance['poses_with_intersections']}),flush=True)
